      "ballot_id": "B024",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics made individual artificial atoms and microwave photons controllable in a solid-state device, opening a major new regime for quantum optics and quantum information.",
        "attribution": "The theoretical framework and experimental demonstrations were mutually essential; these three represent foundational theory, early experiments, and the development of the platform.",
        "maturity": "The field has been established for decades and its central effects have been reproduced and extended across many laboratories.",
        "uncertainties": [
          "The discovery was collective, so a three-person award would necessarily omit important early contributors."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "AdS/CFT is a profound duality linking gauge theories and gravity, with deep consequences for quantum field theory, black-hole physics, and quantum gravity.",
        "attribution": "Maldacena's conjecture established the correspondence; Witten's work clarified its structure and broad significance.",
        "maturity": "The duality has been tested and applied extensively as a theoretical framework, although it is not an experimentally verified description of our universe.",
        "uncertainties": [
          "The physical status of holographic duality as a description of nature remains open."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and experimental realization of topological insulators revealed robust quantum states protected by topology and reshaped condensed matter physics.",
        "attribution": "Kane and Mele developed the theoretical prediction; Molenkamp's experiments provided a decisive demonstration of the quantum spin Hall effect.",
        "maturity": "The phenomena are well established, with many material realizations and extensive experimental confirmation.",
        "uncertainties": [
          "The long-term distinction between this discovery and the broader topological matter program may be difficult to define."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B057",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can, in principle, be protected against noise, turning quantum computing from a fragile ideal into a physically meaningful framework.",
        "attribution": "Shor and Steane introduced influential quantum codes, while Kitaev's topological codes connected error correction to robust phases of matter.",
        "maturity": "The theory is foundational and has motivated extensive experiments; scalable fault-tolerant operation remains an active goal.",
        "uncertainties": [
          "The credited advances span distinct but connected ideas, making the boundaries of a single award difficult to set."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks brought atomic timekeeping to a new level of precision and enabled new tests of fundamental physics and measurements of gravitational potential.",
        "attribution": "Katori introduced the lattice clock concept and demonstrated its key advantages; Ye led complementary advances in precision, control, and clock performance.",
        "maturity": "The method is mature, independently realized, and already supports a wide range of precision measurements.",
        "uncertainties": [
          "The field includes substantial contributions from other clock groups, though the credited pair captures central advances."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Gerhard Rempe",
        "H. Jeff Kimble",
        "Mikhail Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Coherent light-matter interfaces made it possible to map quantum states between photons and matter, a key physical step toward quantum networks.",
        "attribution": "These researchers made complementary contributions to cavity-based atom-photon coupling, quantum optical interfaces, and memory and network protocols.",
        "maturity": "The central interface physics has been demonstrated repeatedly, while large-scale network operation remains developmental.",
        "uncertainties": [
          "The proposed discovery encompasses several related interface techniques rather than one sharply bounded result."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Titanium-sapphire lasers and passive femtosecond mode-locking transformed ultrafast science by making short, tunable pulses practical and reliable.",
        "attribution": "Moulton's laser medium and the independent advances in mode-locking by Keller and Sibbett represent the complementary foundations of the capability.",
        "maturity": "The technology has been established for decades and enabled broad, reproducible work across physics.",
        "uncertainties": [
          "The award would need to distinguish the underlying physics from the many subsequent engineering contributions."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Kazumasa A. Takeuchi",
        "Mehran Kardar",
        "Yi-Cheng Zhang"
      ],
      "assessment": {
        "nobel_worthiness": "Kardar-Parisi-Zhang universality connects growth processes across very different systems and offers a powerful, widely applicable account of nonequilibrium fluctuations.",
        "attribution": "Kardar and Zhang established the theory; Takeuchi's experiments gave unusually clear quantitative confirmation of its scaling predictions.",
        "maturity": "The universality class is well developed theoretically and experimentally, with confirmation in distinct settings.",
        "uncertainties": [
          "The breadth of the universality class makes it challenging to specify which theoretical and experimental milestones define the prize."
        ]
      }
    }
  ]
